from pathlib import Path
from copy import deepcopy
from docx import Document

root=Path(__file__).resolve().parent
doc=Document(root/'aphrodize_report_5_chapters.docx')
anchor=next(p for p in doc.paragraphs if p.text=='2 5 สิทธิ์ข้อมูลและความยินยอม')
insert=Document()
def h(text): insert.add_heading(text,3)
def p(text): insert.add_paragraph(text)

h('2 4 1 Redis')
p('Redis เป็นระบบเก็บข้อมูลแบบ key value ที่ทำงานในหน่วยความจำ ใน Aphrodize ใช้เป็นตัวกลางสำหรับคิวงานและการประสาน worker แทนการประมวลผลภาพหรือฝึกโมเดลภายในคำขอ HTTP โดยตรง API ส่งรหัสงานเข้า Redis จากนั้น worker ที่รับผิดชอบคิวนั้นจึงนำงานไปทำ ข้อมูลภาพไม่ได้ส่งทั้งไฟล์ในคิว แต่เก็บใน MinIO และให้ worker อ่านจากตำแหน่งที่ระบุในฐานข้อมูล')
p('โครงการแยกคิว inference และ training เพื่อแยกประเภทงาน Compose ใช้ Redis 7 เปิด Append Only File หรือ AOF บันทึกการเปลี่ยนแปลงลงดิสก์ เก็บข้อมูลใน volume และกำหนดรหัสผ่านจาก environment การตั้งค่านี้ช่วยรักษาข้อมูลคิวเมื่อเริ่ม container ใหม่ แต่ไม่ใช่หลักประกันว่างานจะสำเร็จทุกกรณี PostgreSQL ยังคงเป็นแหล่งข้อมูลหลักของบันทึกและผลลัพธ์ ส่วน Redis ต้องตรวจร่วมกับสถานะงานและ worker')

h('2 4 2 ARQ')
p('ARQ เป็นไลบรารีคิวงานสำหรับ Python ที่ใช้ Redis และทำงานร่วมกับ asyncio หน้าที่ของ ARQ คือรับคำสั่งจากผู้ส่งงาน จัดเก็บงานในคิว และเรียกฟังก์ชันที่ลงทะเบียนใน worker จึงแตกต่างจาก Redis ซึ่งเป็นที่เก็บข้อมูลและตัวกลางคิว ส่วน ARQ เป็นกลไกจัดการการทำงานของงานนั้น')
p('ตัวอย่างการวิเคราะห์ภาพคือ API เรียก enqueue_job เพื่อส่ง run_inference พร้อม analysis_id ไปยังคิว inference แล้วตอบรหัสงานให้เว็บอ่านสถานะภายหลัง ระบบยังลงทะเบียนงานล้างไฟล์และงานส่งภาพให้ Label Studio รวมถึงกำหนดงานตามเวลาได้ การส่งงานเข้าคิวสำเร็จไม่ได้หมายความว่าประมวลผลเสร็จ เว็บต้องอ่านสถานะ queued running completed rejected หรือ failed จาก API และฐานข้อมูล')

h('2 4 3 Inference worker')
p('Inference worker เป็นกระบวนการ Python ที่อ่านคิว inference ผ่าน ARQ เมื่อรับงานจะโหลดข้อมูลการวิเคราะห์จาก PostgreSQL เปลี่ยนสถานะเป็น running และอ่านภาพต้นฉบับจาก MinIO จากนั้นตรวจคุณภาพ จัดแนวภาพ วิเคราะห์พื้นที่ริ้วรอย และสร้างข้อมูลรายบริเวณกับภาพประกอบเมื่อมีผลรองรับ')
p('worker บันทึกผลเชิงโครงสร้างลง PostgreSQL และเก็บไฟล์ mask overlay regions และ outline ใน MinIO โค้ดกำหนด max_jobs เท่ากับ 1 เพื่อให้ worker นี้ทำงานคิวครั้งละหนึ่งงาน ก่อนเพิ่มจำนวนงานพร้อมกันต้องวัดหน่วยความจำและเวลารอ นอกจากนี้มีงานล้างไฟล์ตามอายุ และงานตรวจความสอดคล้องของ annotation เมื่อเริ่ม worker และทุกต้นชั่วโมง การลบต้นฉบับเป็นขั้นตอนที่พยายามทำแม้งานล้มเหลว แต่ยังต้องติดตามข้อผิดพลาดการลบ')

h('2 4 4 Trainer worker')
p('Trainer worker อ่านคิว training แยกจากงานวิเคราะห์ภาพ เพื่อฝึกโมเดลรุ่นใหม่โดยไม่เปลี่ยนรุ่นที่ให้บริการทันที เส้นทางฝึกภาพใช้ชุดข้อมูลภายนอกที่ได้รับอนุญาตและอนุมัติแล้ว ส่วน Daily Health จับคู่ข้อมูลวันที่ D กับผลที่ผู้ใช้รายงานวันที่ D+1 ภายใต้ความยินยอมสำหรับการฝึก ไม่ใช้ค่าพยากรณ์แทนผลจริง')
p('Daily Health มีงานตรวจความพร้อมทุกวันจันทร์เวลา 09:00 น. ประเทศไทย หรือ 02:00 UTC และไม่ตรวจทันทีเมื่อเริ่ม worker หากจำนวนข้อมูลและเงื่อนไขครบจึงส่งงานฝึก candidate ผลต้องผ่านการประเมินเทียบวิธีพื้นฐานและการอนุมัติก่อนเปิดใช้ การฝึก time series และ tabular แบบทั่วไปยังบันทึกเพียง metadata ของการทดลอง จึงไม่ควรนับเป็นโมเดลที่ฝึกเสร็จแล้ว')

h('2 4 5 PostgreSQL และ SQLAlchemy')
p('PostgreSQL เป็นฐานข้อมูลเชิงสัมพันธ์ ใช้จัดเก็บข้อมูลที่ต้องเชื่อมโยงกัน เช่น บัญชี ความยินยอม บันทึกสุขภาพ สถานะงาน ผลวิเคราะห์ งาน annotation และประวัติรุ่นโมเดล API และ worker อ่านข้อมูลชุดเดียวกัน ทำให้ติดตามงานจากรหัสงานได้ และแสดงข้อมูลของบัญชีหลังรีเฟรชหน้าเว็บได้โดยไม่อาศัยข้อมูลในเบราว์เซอร์เพียงอย่างเดียว')
p('SQLAlchemy เป็นชั้นเชื่อมต่อระหว่างโค้ด Python กับฐานข้อมูล ช่วยจัดการแบบจำลองตาราง คำสั่งอ่านเขียนและ transaction ส่วน migration ใช้จัดการการเปลี่ยนโครงสร้างฐานข้อมูล ไฟล์ภาพไม่เก็บเป็นข้อมูลหลักในตาราง แต่เก็บรหัสอ้างอิงไฟล์ใน MinIO การแยกข้อมูลเช่นนี้ทำให้ฐานข้อมูลรับผิดชอบความสัมพันธ์และผลลัพธ์ ส่วน object storage รับผิดชอบไฟล์ขนาดใหญ่')

h('2 4 6 MinIO และ object storage')
p('MinIO เป็นระบบจัดเก็บไฟล์ที่ใช้อินเทอร์เฟซเข้ากันได้กับ S3 โดยจัดไฟล์เป็น object ภายใน bucket โครงการใช้เก็บภาพต้นฉบับชั่วคราว ภาพผลวิเคราะห์ สำเนาสำหรับทบทวน และไฟล์การทดลองบางประเภท ส่วน PostgreSQL เก็บ metadata และตำแหน่งอ้างอิง ไม่เก็บภาพทั้งไฟล์')
p('ภาพวิเคราะห์อยู่ใน bucket ส่วนตัว และอ่านผ่าน API ที่ตรวจเจ้าของบัญชีกับวันหมดอายุ ไฟล์ผลมีอายุเข้าถึง 24 ชั่วโมง แม้งานลบไฟล์ยังไม่ทำงาน API ต้องปฏิเสธการอ่านไฟล์หมดอายุ การหมดอายุภาพไม่เท่ากับการลบผล JSON ในฐานข้อมูลทั้งหมด อีกทั้งไฟล์โมเดล Daily Health และข้อมูล UV บางส่วนเก็บในโฟลเดอร์ที่ mount ไว้ ไม่ได้เก็บทุกไฟล์ใน MinIO')

h('2 4 7 FastAPI')
p('FastAPI เป็นกรอบงานสร้าง API ฝั่ง Python ทำหน้าที่รับคำขอจาก Next.js ตรวจรูปแบบข้อมูล การยืนยันตัวตน สิทธิ์เจ้าของข้อมูล และความยินยอม ก่อนอ่านเขียนฐานข้อมูลหรือส่งงานเข้าคิว ตัวอย่างบริการได้แก่สมัครสมาชิก บันทึกสุขภาพ อ่านประวัติ สร้างงานวิเคราะห์ภาพ และอ่านผลกับไฟล์ประกอบ')
p('งานที่ใช้เวลานาน เช่น วิเคราะห์ภาพและฝึกโมเดล ถูกส่งไป worker ส่วนคำขออ่านผลคืนสถานะและข้อมูลที่บันทึกไว้ ไม่ฝึกโมเดลใหม่ทุกครั้งที่เปิดหน้าเว็บ เมื่อข้อมูลหรือรุ่นโมเดลไม่พร้อม API ต้องแจ้งสถานะตามจริง การตอบ health check สำเร็จยืนยันเพียงความพร้อมเบื้องต้น ไม่ยืนยันว่า token ไฟล์โมเดลหรือทุก endpoint ใช้งานได้')

h('2 4 8 Next js และส่วนติดต่อผู้ใช้')
p('Next.js เป็นส่วนหน้าเว็บและตัวกลางฝั่ง server เบราว์เซอร์แสดงฟอร์ม ผลภาพ กราฟ ประวัติและแผนที่ ส่วน server route ส่งคำขอไป FastAPI และจัดการ session โดยใช้ cookie ที่ JavaScript ฝั่งหน้าเว็บอ่านไม่ได้ ไม่ส่ง service credential หรือ admin credential ให้เบราว์เซอร์')
p('หน้าวิเคราะห์ภาพส่งงานแล้วอ่านสถานะซ้ำจนได้ผล หน้าประวัติอ่านข้อมูลตามบัญชี ส่วนกราฟ Trends แยกค่าที่บันทึกจริงกับค่าประมาณ พร้อมหน่วยและวันเป้าหมาย หน้าที่ของหน้าเว็บคือสื่อความหมายและข้อจำกัดของข้อมูล ไม่เติมคะแนนที่ backend ไม่มี และไม่ถือว่าการแสดงหน้าจอสำเร็จเป็นหลักฐานความแม่นยำของโมเดล')

h('2 4 9 MLflow')
p('MLflow ใช้ติดตามการทดลอง โดยเก็บชื่อการทดลอง รหัส run การตั้งค่า ตัวชี้วัดและข้อมูลรุ่น เพื่อเปรียบเทียบและตรวจย้อนกลับ Compose ตั้ง backend store ของ MLflow เป็นฐานข้อมูล mlflow บน PostgreSQL และกำหนดพื้นที่เก็บ artifact เป็น bucket mlflow บน MinIO สำหรับเส้นทางที่ส่งไฟล์การทดลอง')
p('Daily Health ส่งเฉพาะตัวชี้วัดสรุปและจำนวนข้อมูลเข้า MLflow ไม่ส่งบันทึกสุขภาพรายบุคคล รหัสผู้เข้าร่วม หรือไฟล์โมเดลสุขภาพไปด้วย ส่วนการฝึกภาพและ UV มีการติดตามไฟล์ตามเส้นทางของตน MLflow ไม่ใช่ตัวอนุมัติ deployment การมี run ที่สำเร็จหรือมีไฟล์โมเดลไม่ได้แปลว่ารุ่นนั้นถูกเปิดให้ผู้ใช้ใช้งานแล้ว')

h('2 4 10 Label Studio')
p('Label Studio เป็นเครื่องมือให้มนุษย์สร้างหรือทบทวนป้ายกำกับภาพ เช่น หน้ากากอ้างอิงบริเวณริ้วรอย Aphrodize เชื่อมผ่าน SDK เพื่อสร้าง task เมื่อมีความยินยอมสำหรับ annotation แยกจากความยินยอมวิเคราะห์ภาพ การส่ง task ต้องมี token และสิทธิ์ project ของ instance ที่ถูกต้อง')
p('ภาพทบทวนถูกส่งเป็นข้อมูลภาพแบบ base64 ภายใน task จึงมีสำเนาใน Label Studio ที่ต้องจัดการอายุและการลบด้วย งานวิเคราะห์ถูกบันทึกก่อนเริ่มสาขา review เพื่อไม่ให้ปัญหา SDK ทำให้ผลวิเคราะห์สูญหาย ปัจจุบันยังไม่มีขั้นรับ annotation กลับ ตรวจรับ และสร้าง dataset version ที่เชื่อมสู่การฝึกอัตโนมัติ การมี task จึงไม่เท่ากับมีข้อมูลที่ได้รับอนุญาตพร้อมฝึก')

h('2 4 11 UV refresh และ UV training')
p('งาน UV แยกจากคิว ARQ ใช้สคริปต์และโฟลเดอร์ข้อมูลที่ mount ไว้เพื่อรับข้อมูลย้อนหลัง ฝึก SARIMAX ประเมินรุ่น และสร้างไฟล์ snapshot สำหรับ API อ่าน งาน refresh ทำหน้าที่สร้างค่าประมาณจากรุ่นที่ใช้งาน ส่วน training ทำหน้าที่สร้างและประเมินรุ่นใหม่ จึงเป็นคนละขั้นตอน')
p('เมื่อเปิดบริการตาม profile งาน uv refresh เริ่มทำงานแล้วเว้น 6 ชั่วโมงหากสำเร็จ หรือ 30 นาทีเมื่อผิดพลาด ส่วน uv training เริ่มเมื่อเปิดบริการแล้วเว้น 30 วันหากสำเร็จ หรือ 1 วันเมื่อผิดพลาด จึงไม่ใช่ cron รายเดือนตามวันปฏิทิน ผู้ดูแลต้องอนุมัติการเปลี่ยนรุ่น และ API ตรวจความสดของ snapshot ก่อนแสดงผล โมเดลทดลองรองรับกรุงเทพฯ เชียงใหม่และสงขลา ไม่ใช่การพยากรณ์ทุกจังหวัด')

h('2 4 12 Docker Compose และการติดตามสถานะ')
p('Docker Compose กำหนดบริการ image เครือข่าย environment volume และเงื่อนไขเริ่มงานในไฟล์ compose.yml เพื่อให้ API ฐานข้อมูล คิว storage และ worker เชื่อมต่อกันตามชื่อบริการ มี profile แยกบริการ AI งานสาธิตและงาน UV บางส่วน จึงไม่ใช่ว่าทุกบริการจะเริ่มด้วยคำสั่งพื้นฐานเพียงคำสั่งเดียว')
p('health check ใช้ตรวจความพร้อมพื้นฐาน เช่น PostgreSQL รับการเชื่อมต่อ Redis ตอบ PONG และหน้า login ของ Label Studio ตอบกลับ ส่วน Docker logs และ monitoring API ช่วยดูงานล้มเหลว เวลารอและความสดของ UV ขณะนี้ไม่ควรอ้างว่ามี OpenTelemetry Grafana Loki และ Tempo ครบตามภาพแนวคิด การสำรองและกู้คืน volume ต้องตรวจแยกจากการ restart container และไม่ใช้การลบ volume เป็นขั้นตอน restart ปกติ')

h('2 4 13 ความสัมพันธ์ระหว่างองค์ประกอบ')
p('ตัวอย่างงานหนึ่งเริ่มจากผู้ใช้ส่งภาพผ่าน Next.js ไป FastAPI จากนั้น API บันทึกรายการงานใน PostgreSQL เก็บภาพใน MinIO และใช้ ARQ ส่งรหัสงานผ่าน Redis เมื่อ inference worker รับงานจะอ่านภาพ ประมวลผล เก็บผลกลับฐานข้อมูลและ storage แล้วให้เว็บอ่านผลผ่าน API งาน review และ training เป็นสาขาแยกที่มีเงื่อนไขสิทธิ์ข้อมูลและการอนุมัติของตน')
p('Redis กับ ARQ จึงไม่ใช่ฐานข้อมูลผลวิเคราะห์ MinIO ไม่ได้อนุมัติโมเดล และ MLflow ไม่ได้ฝึกหรือเปิดรุ่นใหม่ด้วยตนเอง การแบ่งบทบาทเช่นนี้ช่วยให้ตรวจปัญหาได้ตรงส่วน เช่น งานค้างให้ตรวจคิวและ worker ภาพอ่านไม่ได้ให้ตรวจสิทธิ์และ storage ส่วนรุ่นโมเดลไม่พร้อมให้ตรวจไฟล์ เกณฑ์คุณภาพและสถานะอนุมัติ')

